  "script": "const fields = $vars.extractInvoiceFields.output.ExtractionResult.ResultsDocument.Fields || [];\nconst get = (name) => (fields.find(f => f.FieldName === name) || {}).Values?.[0] || null;\nreturn {\n  invoiceNumber: get('InvoiceNumber'),\n  invoiceDate: get('InvoiceDate'),\n  totalAmount: get('TotalAmount'),\n  vendorName: get('VendorName'),\n  currency: get('Currency')\n};"
